service = moduleRef.get(TasksService)

Behavior example
it("sets completedAt when moving IN_PROGRESS -> DONE", async () => {
fake.seed(task({ status: "IN_PROGRESS", completedAt: null }))

const result = await service.updateStatus(
TASK_ID,
user,
"DONE",
)

expect(result.status).toBe("DONE")
expect(result.completedAt).not.toBeNull()
})

Do not assert implementation trivia
Prefer outcomes and meaningful repository interactions over assertions like “private helper
X was called once”. Private implementation can change while public behavior stays correct.

