import { describe, expect, it } from "vitest";
import { assertTaskStatusTransition, TaskStatusTransitionNotAllowed } from "./task-status.policy";

describe("assertTaskStatusTransition", () => {
  it.each([
    ["TODO", "IN_PROGRESS"],
    ["TODO", "CANCELED"],
    ["IN_PROGRESS", "DONE"],
    ["DONE", "IN_PROGRESS"],
  ] as const)("allows %s -> %s", (from, to) => {
    expect(() => assertTaskStatusTransition(from, to)).not.toThrow();
  });

  it("rejects DONE -> TODO", () => {
    expect(() => assertTaskStatusTransition("DONE", "TODO"))
      .toThrow(TaskStatusTransitionNotAllowed);
  });
});

export type TaskStatus = "TODO" | "IN_PROGRESS" | "DONE" | "CANCELED";

const allowed: Record<TaskStatus, readonly TaskStatus[]> = {
  TODO: ["IN_PROGRESS", "CANCELED"],
  IN_PROGRESS: ["TODO", "DONE", "CANCELED"],
  DONE: ["IN_PROGRESS"],
  CANCELED: [],
};

export class TaskStatusTransitionNotAllowed extends Error {}

export function assertTaskStatusTransition(from: TaskStatus, to: TaskStatus) {
  if (!allowed[from].includes(to)) {
    throw new TaskStatusTransitionNotAllowed(`${from} -> ${to}`);
  }
}

